#include <stdio.h>

int main(void) {
    int N, V[500];
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &V[i]);
    }

    int answer = 1;

    for (int a = 1; a <= N; a++) {
        for (int b = a + 1; b <= N; b++) {
            int last = 0;
            int count = 0;

            for (int i = 0; i < N; i++) {
                if (V[i] == a || V[i] == b) {
                    if (V[i] != last) {
                        count++;
                        last = V[i];
                    }
                }
            }

            if (count > answer) answer = count;
        }
    }

    printf("%d\n", answer);
    return 0;
}
